mapper.select:
SELECT pp.PORTFOLIO_ID id, pp.PORTFOLIO_NAME text FROM PTL_PORTFOLIO_AUTHORITY pa INNER JOIN PTL_PORTFOLIO pp on pa.portfolio_id = pp.portfolio_id
AND (pp.PORTFOLIO_ID LIKE CONCAT('%',CONCAT(#{search},'%')) OR pp.PORTFOLIO_NAME LIKE CONCAT('%',CONCAT(#{search},'%')))
AND pa.USER_ID = #{userId}
